S2.sql:
-- Q35. Create a trigger that stops a student from joining a team that is already full.
CREATE OR REPLACE FUNCTION check_team_capacity() RETURNS TRIGGER AS $$
DECLARE
    current_size INT;
    capacity     INT;
BEGIN
    SELECT max_size INTO capacity FROM team WHERE team_id = NEW.team_id FOR UPDATE;
    SELECT COUNT(*) INTO current_size FROM team_member WHERE team_id = NEW.team_id;
    IF current_size >= capacity THEN
        RAISE EXCEPTION 'Team % is full (% / %)', NEW.team_id, current_size, capacity;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_team_capacity
BEFORE INSERT ON team_member
FOR EACH ROW EXECUTE FUNCTION check_team_capacity();

-- body_trigger_q35() in experiments/race/harness.py ($1 = 'T02', $2 = the racer's USN)
INSERT INTO team_member (team_id, usn, role, joined_at) VALUES ($1, $2, 'member', current_date);
-- the BEFORE INSERT trigger above locks the team row FOR UPDATE, then COUNTs

S3.sql:
CREATE TABLE exp.team_counter (
    team_id      VARCHAR(5) PRIMARY KEY REFERENCES team(team_id) ON DELETE CASCADE,
    member_count INT NOT NULL CHECK (member_count >= 0),
    max_size     INT NOT NULL,
    CHECK (member_count <= max_size)              -- belt and braces: the counter itself can never overflow
);

-- body_counter() in experiments/race/harness.py ($1 = 'T02', $2 = the racer's USN)
UPDATE exp.team_counter SET member_count = member_count + 1 
WHERE team_id = $1 AND member_count < max_size RETURNING member_count;
INSERT INTO team_member (team_id, usn, role, joined_at) VALUES ($1, $2, 'member', current_date);
-- no row back from the UPDATE -> ROLLBACK ("team is full")

